WITH recent_employees AS (SELECT * FROM employees WHERE NOT (level = 'L1' AND (is_remote = TRUE OR level IN ('L1', 'L3')))), agg AS (SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END hire_cohort, dept_id, ROUND(STDDEV(salary), 2) stddev_salary FROM recent_employees GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END, dept_id) SELECT hire_cohort, dept_id, stddev_salary FROM agg
